(170, 1, 'Which statement shows an error dialog with the message Wrong input and the title Error?', 'JOptionPane.showMessageDialog(null, "Wrong input", "Error", JOptionPane.ERROR_MESSAGE);', 'JOptionPane.showMessageDialog(null, "Wrong input", "Error" JOptionPane.ERROR_MESSAGE);', 'JOptionPane.showMessageDialog("Wrong input", "Error", JOptionPane.ERROR_MESSAGE);', 'JOptionPane.showMessageDialog(null, "Wrong input", "Error", JOptionPane.ERROR_MSG);'),
(171, 1, 'Which code imports Scanner and creates a Scanner named scan for keyboard input?', 'import java.util.Scanner; Scanner scan = new Scanner(System.in);', 'import java.util.Scanner; Scanner scan = new Scanner(System.out);', 'import java.util.Scanner; Scanner scan = Scanner(System.in);', 'import java.io.Scanner; Scanner scan = new Scanner(System.in);'),
(172, 1, 'Which code prompts for the first number and stores it as an int with a Scanner?', 'System.out.println("Input the first number to add:"); int num1 = scan.nextInt();', 'System.out.println("Input the first number to add:"); int num1 = scan.nextLine();', 'System.out.println("Input the first number to add:"); int num1 = scan.readInt();', 'System.out.println("Input the first number to add:"); int num1 = Scanner.nextInt();'),
